        if (dryDays[i] > previous) { chosen = i; break; }
      }
      if (chosen === -1) return [];
      answer[dryDays[chosen]] = lake;
      dryDays.splice(chosen, 1);
    }
    lastRain.set(lake, day);
  }
  return answer;
}
